package store

import "fmt"

func (s *Store) initializeMCPExecution() error {
	tx, err := s.db.Begin()
	if err != nil {
		return err
	}
	defer tx.Rollback()
	statements := []string{
		`CREATE TABLE IF NOT EXISTS mcp_proposal_sources (model_invocation_id TEXT PRIMARY KEY REFERENCES invocations(id),mission_id TEXT NOT NULL REFERENCES missions(id),version INTEGER NOT NULL,epoch INTEGER NOT NULL,session_id TEXT NOT NULL,data BLOB NOT NULL CHECK(json_valid(data)),digest TEXT NOT NULL)`,
		`CREATE TABLE IF NOT EXISTS mcp_call_proposals (id TEXT PRIMARY KEY,mission_id TEXT NOT NULL REFERENCES missions(id),version INTEGER NOT NULL,epoch INTEGER NOT NULL,session_id TEXT NOT NULL,source_invocation_id TEXT NOT NULL UNIQUE REFERENCES mcp_proposal_sources(model_invocation_id),data BLOB NOT NULL CHECK(json_valid(data)),digest TEXT NOT NULL)`,
		`CREATE TABLE IF NOT EXISTS mcp_call_decisions (request_id TEXT NOT NULL,mission_id TEXT NOT NULL REFERENCES missions(id),version INTEGER NOT NULL,proposal_id TEXT NOT NULL UNIQUE REFERENCES mcp_call_proposals(id),proposal_digest TEXT NOT NULL,expected_revision INTEGER NOT NULL,approve INTEGER NOT NULL CHECK(approve IN (0,1)),grant_id TEXT NOT NULL,invocation_id TEXT NOT NULL,PRIMARY KEY(mission_id,request_id))`,
		`CREATE TABLE IF NOT EXISTS mcp_call_grants (id TEXT PRIMARY KEY,mission_id TEXT NOT NULL REFERENCES missions(id),version INTEGER NOT NULL,epoch INTEGER NOT NULL,session_id TEXT NOT NULL,proposal_id TEXT NOT NULL UNIQUE REFERENCES mcp_call_proposals(id),data BLOB NOT NULL CHECK(json_valid(data)),digest TEXT NOT NULL)`,
		`CREATE TABLE IF NOT EXISTS mcp_invocations (id TEXT PRIMARY KEY,mission_id TEXT NOT NULL REFERENCES missions(id),version INTEGER NOT NULL,epoch INTEGER NOT NULL,session_id TEXT NOT NULL,ordinal INTEGER NOT NULL,proposal_id TEXT NOT NULL UNIQUE REFERENCES mcp_call_proposals(id),grant_id TEXT NOT NULL UNIQUE REFERENCES mcp_call_grants(id),intent BLOB NOT NULL CHECK(json_valid(intent)),digest TEXT NOT NULL,reserved_result_bytes INTEGER NOT NULL CHECK(reserved_result_bytes=65536),status TEXT NOT NULL CHECK(status IN ('authorized_pending','dispatching','succeeded','failed','outcome_unknown','interrupted_before_dispatch','interrupted_before_call')),phase TEXT NOT NULL CHECK(phase IN ('preflight','call_started')),result BLOB CHECK(result IS NULL OR json_valid(result)),error_code TEXT NOT NULL DEFAULT '',requests INTEGER NOT NULL DEFAULT 0 CHECK(requests>=0 AND requests<=14),request_bytes INTEGER NOT NULL DEFAULT 0 CHECK(request_bytes>=0 AND request_bytes<=14680064),response_bytes INTEGER NOT NULL DEFAULT 0 CHECK(response_bytes>=0 AND response_bytes<=4194304),duration_millis INTEGER NOT NULL DEFAULT 0 CHECK(duration_millis>=0),dispatched_at TEXT NOT NULL DEFAULT '',finished_at TEXT NOT NULL DEFAULT '',UNIQUE(mission_id,ordinal))`,
		`CREATE UNIQUE INDEX IF NOT EXISTS one_active_mcp_invocation ON mcp_invocations(mission_id) WHERE status IN ('authorized_pending','dispatching')`,
		`CREATE TABLE IF NOT EXISTS mcp_invocation_transitions (seq INTEGER PRIMARY KEY AUTOINCREMENT,invocation_id TEXT NOT NULL REFERENCES mcp_invocations(id),mission_id TEXT NOT NULL REFERENCES missions(id),version INTEGER NOT NULL,from_status TEXT NOT NULL,to_status TEXT NOT NULL,phase TEXT NOT NULL,created_at TEXT NOT NULL)`,
		`CREATE TRIGGER IF NOT EXISTS immutable_mcp_bindings BEFORE UPDATE OF data ON missions WHEN COALESCE(json_extract(OLD.data,'$.mcp_bindings'),'') IS NOT COALESCE(json_extract(NEW.data,'$.mcp_bindings'),'') BEGIN SELECT RAISE(ABORT,'MCP bindings immutable'); END`,
		`CREATE TRIGGER IF NOT EXISTS mcp_source_owner BEFORE INSERT ON mcp_proposal_sources WHEN NEW.version=1 AND NOT EXISTS(SELECT 1 FROM invocations WHERE id=NEW.model_invocation_id AND mission_id=NEW.mission_id AND epoch=NEW.epoch AND session_id=NEW.session_id AND kind='model' AND role='researcher' AND status='authorized_pending') BEGIN SELECT RAISE(ABORT,'invalid MCP source owner'); END`,
		`CREATE TRIGGER IF NOT EXISTS mcp_proposal_owner BEFORE INSERT ON mcp_call_proposals WHEN NEW.version=1 AND NOT EXISTS(SELECT 1 FROM mcp_proposal_sources s JOIN invocations i ON i.id=s.model_invocation_id WHERE s.model_invocation_id=NEW.source_invocation_id AND s.mission_id=NEW.mission_id AND s.epoch=NEW.epoch AND s.session_id=NEW.session_id AND s.version=1 AND i.status='succeeded') BEGIN SELECT RAISE(ABORT,'invalid MCP proposal owner'); END`,
		`CREATE TRIGGER IF NOT EXISTS mcp_grant_owner BEFORE INSERT ON mcp_call_grants WHEN NEW.version=1 AND NOT EXISTS(SELECT 1 FROM mcp_call_proposals WHERE id=NEW.proposal_id AND mission_id=NEW.mission_id AND epoch=NEW.epoch AND session_id=NEW.session_id AND version=1) BEGIN SELECT RAISE(ABORT,'invalid MCP grant owner'); END`,
		`CREATE TRIGGER IF NOT EXISTS mcp_invocation_owner BEFORE INSERT ON mcp_invocations WHEN NEW.version=1 AND NOT EXISTS(SELECT 1 FROM mcp_call_grants WHERE id=NEW.grant_id AND mission_id=NEW.mission_id AND proposal_id=NEW.proposal_id AND epoch=NEW.epoch AND session_id=NEW.session_id AND version=1) BEGIN SELECT RAISE(ABORT,'invalid MCP invocation owner'); END`,
		`CREATE TRIGGER IF NOT EXISTS mcp_transition_owner BEFORE INSERT ON mcp_invocation_transitions WHEN NEW.version=1 AND NOT EXISTS(SELECT 1 FROM mcp_invocations WHERE id=NEW.invocation_id AND mission_id=NEW.mission_id AND version=1) BEGIN SELECT RAISE(ABORT,'invalid MCP transition owner'); END`,
		`CREATE TRIGGER IF NOT EXISTS mcp_transition_sequence BEFORE INSERT ON mcp_invocation_transitions WHEN NEW.version=1 AND (
 julianday(NEW.created_at) IS NULL OR NEW.created_at NOT GLOB '????-??-??T??:??:??*Z'
 OR NOT EXISTS(SELECT 1 FROM mcp_invocations WHERE id=NEW.invocation_id AND mission_id=NEW.mission_id AND version=1 AND status=NEW.to_status AND phase=NEW.phase)
 OR (NOT EXISTS(SELECT 1 FROM mcp_invocation_transitions WHERE invocation_id=NEW.invocation_id) AND (NEW.from_status!='' OR NEW.to_status!='authorized_pending' OR NEW.phase!='preflight'))
 OR (EXISTS(SELECT 1 FROM mcp_invocation_transitions WHERE invocation_id=NEW.invocation_id) AND NOT EXISTS(
 SELECT 1 FROM mcp_invocation_transitions p WHERE p.seq=(SELECT MAX(seq) FROM mcp_invocation_transitions WHERE invocation_id=NEW.invocation_id)
 AND p.version=1 AND p.mission_id=NEW.mission_id AND p.to_status=NEW.from_status AND julianday(NEW.created_at)>=julianday(p.created_at)
 AND ((p.to_status='authorized_pending' AND NEW.to_status IN ('dispatching','interrupted_before_dispatch') AND NEW.phase='preflight')
 OR (p.to_status='dispatching' AND p.phase='preflight' AND NEW.to_status='dispatching' AND NEW.phase='call_started')
 OR (p.to_status='dispatching' AND NEW.phase=p.phase AND (NEW.to_status='failed' OR (p.phase='call_started' AND NEW.to_status IN ('succeeded','outcome_unknown')) OR (p.phase='preflight' AND NEW.to_status='interrupted_before_call'))))))
 ) BEGIN SELECT RAISE(ABORT,'invalid MCP transition sequence'); END`,
		`CREATE TRIGGER IF NOT EXISTS mcp_invocation_initial BEFORE INSERT ON mcp_invocations WHEN NEW.status!='authorized_pending' OR NEW.phase!='preflight' OR NEW.result IS NOT NULL OR NEW.error_code!='' OR NEW.requests!=0 OR NEW.response_bytes!=0 OR NEW.duration_millis!=0 OR NEW.dispatched_at!='' OR NEW.finished_at!='' BEGIN SELECT RAISE(ABORT,'invalid MCP reservation'); END`,
		`CREATE TRIGGER IF NOT EXISTS mcp_invocation_immutable BEFORE UPDATE ON mcp_invocations WHEN NEW.id IS NOT OLD.id OR NEW.mission_id IS NOT OLD.mission_id OR NEW.version IS NOT OLD.version OR NEW.epoch IS NOT OLD.epoch OR NEW.session_id IS NOT OLD.session_id OR NEW.ordinal IS NOT OLD.ordinal OR NEW.proposal_id IS NOT OLD.proposal_id OR NEW.grant_id IS NOT OLD.grant_id OR NEW.intent IS NOT OLD.intent OR NEW.digest IS NOT OLD.digest OR NEW.reserved_result_bytes IS NOT OLD.reserved_result_bytes BEGIN SELECT RAISE(ABORT,'immutable MCP intent'); END`,
		`CREATE TRIGGER IF NOT EXISTS mcp_phase_fence BEFORE UPDATE ON mcp_invocations WHEN (NEW.phase IS NOT OLD.phase AND NOT (OLD.status='dispatching' AND NEW.status='dispatching' AND OLD.phase='preflight' AND NEW.phase='call_started')) OR (NEW.status='dispatching' AND NEW.request_bytes!=0) OR (OLD.status='dispatching' AND NEW.dispatched_at IS NOT OLD.dispatched_at) OR (NEW.result IS NOT NULL AND NEW.status='failed' AND (NEW.error_code!='tool_error' OR NEW.phase!='call_started')) BEGIN SELECT RAISE(ABORT,'invalid MCP dispatch marker'); END`,
		`CREATE TRIGGER IF NOT EXISTS mcp_initial_request_bytes BEFORE INSERT ON mcp_invocations WHEN NEW.request_bytes!=0 BEGIN SELECT RAISE(ABORT,'invalid MCP request counter'); END`,
		`CREATE TRIGGER IF NOT EXISTS mcp_invocation_transition BEFORE UPDATE ON mcp_invocations WHEN NOT ((OLD.status='authorized_pending' AND NEW.status IN ('dispatching','interrupted_before_dispatch')) OR (OLD.status='dispatching' AND NEW.status='dispatching' AND OLD.phase='preflight' AND NEW.phase='call_started') OR (OLD.status='dispatching' AND NEW.status IN ('succeeded','failed','outcome_unknown','interrupted_before_call'))) OR (OLD.phase='call_started' AND NEW.phase!='call_started') OR (NEW.status IN ('succeeded','outcome_unknown') AND NEW.phase!='call_started') OR (NEW.status='interrupted_before_call' AND NEW.phase!='preflight') OR (NEW.status='dispatching' AND (NEW.dispatched_at='' OR NEW.finished_at!='' OR NEW.result IS NOT NULL OR NEW.error_code!='' OR NEW.requests!=0 OR NEW.response_bytes!=0 OR NEW.duration_millis!=0)) OR (NEW.status!='dispatching' AND NEW.finished_at='') OR (NEW.status='succeeded' AND (NEW.result IS NULL OR NEW.error_code!='')) OR (NEW.status NOT IN ('succeeded','dispatching') AND NEW.error_code='') OR (NEW.status NOT IN ('succeeded','failed') AND NEW.result IS NOT NULL) BEGIN SELECT RAISE(ABORT,'invalid MCP transition'); END`,
		`CREATE TRIGGER IF NOT EXISTS mcp_active_insert BEFORE INSERT ON mcp_invocations WHEN EXISTS(SELECT 1 FROM invocations WHERE mission_id=NEW.mission_id AND status IN ('authorized_pending','dispatching')) BEGIN SELECT RAISE(ABORT,'active generic invocation'); END`,
		`CREATE TRIGGER IF NOT EXISTS mcp_active_claim BEFORE UPDATE OF status ON mcp_invocations WHEN NEW.status='dispatching' AND EXISTS(SELECT 1 FROM invocations WHERE mission_id=NEW.mission_id AND status IN ('authorized_pending','dispatching')) BEGIN SELECT RAISE(ABORT,'active generic invocation'); END`,
		`CREATE TRIGGER IF NOT EXISTS generic_mcp_active_insert BEFORE INSERT ON invocations WHEN EXISTS(SELECT 1 FROM mcp_invocations WHERE mission_id=NEW.mission_id AND status IN ('authorized_pending','dispatching')) BEGIN SELECT RAISE(ABORT,'active MCP invocation'); END`,
		`CREATE TRIGGER IF NOT EXISTS generic_mcp_active_claim BEFORE UPDATE OF status ON invocations WHEN NEW.status='dispatching' AND EXISTS(SELECT 1 FROM mcp_invocations WHERE mission_id=NEW.mission_id AND status IN ('authorized_pending','dispatching')) BEGIN SELECT RAISE(ABORT,'active MCP invocation'); END`,
		`CREATE TRIGGER IF NOT EXISTS mcp_shared_quota BEFORE INSERT ON mcp_invocations WHEN (SELECT count(*) FROM mcp_invocations WHERE mission_id=NEW.mission_id)+(SELECT count(*) FROM invocations WHERE mission_id=NEW.mission_id AND kind='repository')>=3 OR NEW.reserved_result_bytes+(SELECT COALESCE(sum(reserved_result_bytes),0) FROM mcp_invocations WHERE mission_id=NEW.mission_id)+(SELECT COALESCE(sum(reserved_result_bytes),0) FROM invocations WHERE mission_id=NEW.mission_id AND kind='repository')>196608 BEGIN SELECT RAISE(ABORT,'shared tool quota'); END`,
		`CREATE TRIGGER IF NOT EXISTS generic_mcp_shared_quota BEFORE INSERT ON invocations WHEN NEW.kind='repository' AND EXISTS(SELECT 1 FROM missions WHERE id=NEW.mission_id AND json_extract(data,'$.tool_mode')='controlled_mcp_read_v1') AND ((SELECT count(*) FROM mcp_invocations WHERE mission_id=NEW.mission_id)+(SELECT count(*) FROM invocations WHERE mission_id=NEW.mission_id AND kind='repository')>=3 OR NEW.reserved_result_bytes+(SELECT COALESCE(sum(reserved_result_bytes),0) FROM mcp_invocations WHERE mission_id=NEW.mission_id)+(SELECT COALESCE(sum(reserved_result_bytes),0) FROM invocations WHERE mission_id=NEW.mission_id AND kind='repository')>196608) BEGIN SELECT RAISE(ABORT,'shared tool quota'); END`,
		`CREATE TRIGGER IF NOT EXISTS mcp_source_claim BEFORE UPDATE OF status ON invocations WHEN NEW.status='dispatching' AND NEW.kind='model' AND NEW.role='researcher' AND EXISTS(SELECT 1 FROM missions WHERE id=NEW.mission_id AND json_extract(data,'$.tool_mode')='controlled_mcp_read_v1') AND NOT EXISTS(SELECT 1 FROM mcp_proposal_sources WHERE model_invocation_id=NEW.id AND mission_id=NEW.mission_id AND epoch=NEW.epoch AND session_id=NEW.session_id AND version=1) BEGIN SELECT RAISE(ABORT,'MCP source checkpoint required'); END`,
	}
	for _, table := range []string{"mcp_proposal_sources", "mcp_call_proposals", "mcp_call_decisions", "mcp_call_grants", "mcp_invocation_transitions"} {
		statements = append(statements, fmt.Sprintf(`CREATE TRIGGER IF NOT EXISTS %s_no_update BEFORE UPDATE ON %s BEGIN SELECT RAISE(ABORT,'immutable MCP record'); END`, table, table))
	}
	for _, table := range []string{"mcp_proposal_sources", "mcp_call_proposals", "mcp_call_decisions", "mcp_call_grants", "mcp_invocations", "mcp_invocation_transitions"} {
		statements = append(statements, fmt.Sprintf(`CREATE TRIGGER IF NOT EXISTS %s_no_delete BEFORE DELETE ON %s BEGIN SELECT RAISE(ABORT,'append-only MCP record'); END`, table, table))
	}
	for _, statement := range statements {
		if _, err = tx.Exec(statement); err != nil {
			return fmt.Errorf("initialize MCP execution: %w", err)
		}
	}
	return tx.Commit()
}
